import hmac
import hashlib
import time
import os
import struct
import secrets
from flask import Flask, request, jsonify, abort

app = Flask(__name__)
SECRET_KEY = os.environ.get('SECRET_KEY', secrets.token_hex(32))
MAX_TOKEN_AGE = 3600

class TokenManager:
    """Manages HMAC-based authentication tokens with expiry."""

    def __init__(self, secret):
        self.secret = secret.encode() if isinstance(secret, str) else secret

    def _compute_mac(self, payload_bytes):
        """Compute HMAC-SHA256 over payload."""
        return hmac.new(self.secret, payload_bytes, hashlib.sha256).digest()

    def generate_token(self, user_id, role='user'):
        """Generate a signed token: [version(1)][timestamp(8)][user_id_len(1)][user_id][role_len(1)][role][hmac(32)]"""
        version = b'\x01'
        timestamp = struct.pack('>Q', int(time.time()))
        user_id_bytes = user_id.encode('utf-8')
        role_bytes = role.encode('utf-8')

        # Enforce maximum field lengths
        if len(user_id_bytes) > 127 or len(role_bytes) > 127:
            raise ValueError("Field too long")

        uid_len = struct.pack('B', len(user_id_bytes))
        role_len = struct.pack('B', len(role_bytes))

        payload = version + timestamp + uid_len + user_id_bytes + role_len + role_bytes
        mac = self._compute_mac(payload)
        return (payload + mac).hex()

    def _safe_field_length(self, length_byte, remaining_buffer_size):
        """Validate that field length doesn't exceed remaining buffer.
        Returns True if the length is valid (within bounds)."""
        # Treat as unsigned — length_byte is already 0-255 from indexing bytes
        if length_byte > 127:
            return False
        return length_byte <= remaining_buffer_size

    def verify_token(self, token_hex):
        """Verify and decode a token. Returns (user_id, role, timestamp) or None."""
        try:
            token = bytes.fromhex(token_hex)
        except (ValueError, TypeError):
            return None

        # Minimum: version(1) + timestamp(8) + uid_len(1) + role_len(1) + hmac(32) = 43
        if len(token) < 43:
            return None

        # Check version
        if token[0] != 0x01:
            return None

        # Extract timestamp
        timestamp = struct.unpack('>Q', token[1:9])[0]

        # Check expiry
        now = int(time.time())
        if now - timestamp > MAX_TOKEN_AGE:
            return None

        # Parse user_id
        uid_len_byte = token[9]
        remaining_after_uid_len = len(token) - 10 - 32  # subtract header so far and mac

        if not self._safe_field_length(uid_len_byte, remaining_after_uid_len):
            return None

        uid_end = 10 + uid_len_byte
        user_id = token[10:uid_end].decode('utf-8', errors='replace')

        # Parse role
        if uid_end >= len(token) - 32:
            return None
        role_len_byte = token[uid_end]
        remaining_after_role_len = len(token) - uid_end - 1 - 32

        if not self._safe_field_length(role_len_byte, remaining_after_role_len):
            return None

        role_end = uid_end + 1 + role_len_byte
        role = token[uid_end + 1:role_end].decode('utf-8', errors='replace')

        # Reject tokens with trailing bytes after the MAC to prevent malleability.
        if role_end + 32 != len(token):
            return None

        # Verify HMAC
        payload = token[:role_end]
        expected_mac = self._compute_mac(payload)
        actual_mac = token[role_end:role_end + 32]

        if not hmac.compare_digest(expected_mac, actual_mac):
            return None

        return (user_id, role, timestamp)


token_mgr = TokenManager(SECRET_KEY)

# Simulated user database
USERS_DB = {
    'admin': {'password_hash': None, 'role': 'admin'},
    'alice': {'password_hash': None, 'role': 'user'},
}

def init_users():
    import bcrypt
    USERS_DB['admin']['password_hash'] = bcrypt.hashpw(b'supersecretadmin', bcrypt.gensalt())
    USERS_DB['alice']['password_hash'] = bcrypt.hashpw(b'alicepassword', bcrypt.gensalt())

@app.before_first_request
def setup():
    init_users()

@app.route('/login', methods=['POST'])
def login():
    import bcrypt
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        abort(400)

    username = data['username']
    password = data['password'].encode('utf-8')

    if username not in USERS_DB:
        # Constant-time-ish: still hash to prevent timing
        bcrypt.hashpw(password, bcrypt.gensalt())
        abort(401)

    user = USERS_DB[username]
    if not bcrypt.checkpw(password, user['password_hash']):
        abort(401)

    token = token_mgr.generate_token(username, user['role'])
    return jsonify({'token': token})

@app.route('/admin/data', methods=['GET'])
def admin_data():
    auth_header = request.headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        abort(401)

    token_hex = auth_header[7:]
    result = token_mgr.verify_token(token_hex)

    if result is None:
        abort(401)

    user_id, role, _ = result
    if role != 'admin':
        abort(403)

    return jsonify({'secret': 'classified-data-here', 'user': user_id})

@app.route('/profile', methods=['GET'])
def profile():
    auth_header = request.headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        abort(401)

    token_hex = auth_header[7:]
    result = token_mgr.verify_token(token_hex)

    if result is None:
        abort(401)

    user_id, role, ts = result
    return jsonify({'user_id': user_id, 'role': role, 'issued_at': ts})

if __name__ == '__main__':
    app.run(debug=False, host='127.0.0.1', port=5000)
